import assert from 'node:assert/strict';
import {readFileSync, writeFileSync} from 'node:fs';
const [from, to] = process.argv.slice(2);
let source = readFileSync(from, 'utf8').replaceAll('\r\n', '\n');
const kind = {
  arcs: /^( +)(const arcs = [^\n]+\(self\.arcs\);)$/m,
  ruleIds: /^( +)(const ids = [^\n]+\(self\.rule_ids\);)$/m,
};
assert(source.includes('function _M0MP210JingLan0v03stn10PlanBranch7compile('));
for (const [name, line] of Object.entries(kind)) {
  assert(line.test(source), 'Missing baseline copy for ' + name);
  source = source.replace(line, (_, indent, statement) => [
    'const ' + name + 'Started = performance.now();',
    statement,
    'copyProbe.' + name + '.ms += performance.now() - ' + name + 'Started;',
    'copyProbe.' + name + '.copies++;',
    'copyProbe.' + name + '.items += ' + (name === 'arcs' ? 'arcs' : 'ids') + '.length;',
  ].map(s => indent + s).join('\n'));
}
const header = `const copyProbe = {arcs: {copies:0, items:0, ms:0}, ruleIds: {copies:0, items:0, ms:0}};
process.once('exit', () => console.error(JSON.stringify(copyProbe)));\n`;
writeFileSync(to, header + source);

